488	
489	  // Dump request body.
490	  if (util.isStream(opts.body)) {
491	    opts.body.on('error', nop).destroy()
492	  }
493	
494	  sendCachedValue(handler, opts, result, age, null, false)
495	}
496	
497	/**
498	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions} [opts]
499	 * @returns {import('../../types/dispatcher.d.ts').default.DispatcherComposeInterceptor}
500	 */
501	module.exports = (opts = {}) => {
502	  const {
