/**
 * Derives the origin to key a request by.
 *
 * `opts.origin` is only set when dispatching through an `Agent`. When an
 * interceptor is composed directly onto a `Client` or `Pool` the origin is
 * held by the dispatcher itself and never reaches the interceptor, so fall
 * back to the origin carried by an absolute-form request target and, failing
 * that, to an empty string. A `Client`/`Pool` only ever talks to a single
 * origin, so the remaining parts of the key stay unambiguous.
 *
 * @param {import('../../types/dispatcher.d.ts').default.DispatchOptions} opts
 * @returns {string}
 */
function getEffectiveOrigin (opts) {
  if (opts.origin) {
    return opts.origin.toString()
  }

  const path = opts.path
  if (typeof path === 'string' && (path.startsWith('http://') || path.startsWith('https://'))) {
    try {
      return new URL(path).origin
    } catch {
      // Not a parsable absolute URL, fall through.
    }
  }

  return ''
}

/**
 * @param {import('../../types/dispatcher.d.ts').default.DispatchOptions} opts
 */
function makeCacheKey (opts) {
  const origin = getEffectiveOrigin(opts)

  let fullPath = opts.path || '/'

