'use strict'

const { createServer } = require('node:http')
const { describe, test, after } = require('node:test')
const { once } = require('node:events')
const { strictEqual } = require('node:assert')
const { setTimeout: sleep } = require('node:timers/promises')
const { Client, Pool, interceptors } = require('../../index')

// `opts.origin` is only set when dispatching through an `Agent`. When the
// cache() and deduplicate() interceptors are composed directly onto a Client
// or a Pool they must still key requests instead of silently doing nothing.
describe('Interceptors composed onto a Client/Pool', () => {
  test('cache() caches responses on a Client', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      requestsToOrigin++
      res.setHeader('cache-control', 'public, s-maxage=100')
      res.end('response-body')
    }).listen(0)

    after(() => server.close())
    await once(server, 'listening')

    const client = new Client(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(() => client.close())

    const first = await client.request({ method: 'GET', path: '/' })
    strictEqual(await first.body.text(), 'response-body')
    strictEqual(requestsToOrigin, 1)

    const second = await client.request({ method: 'GET', path: '/' })
    strictEqual(await second.body.text(), 'response-body')
    strictEqual(requestsToOrigin, 1, 'second request should be served from the cache')
  })

  test('cache() caches responses on a Pool', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      requestsToOrigin++
      res.setHeader('cache-control', 'public, s-maxage=100')
      res.end('response-body')
    }).listen(0)

    after(() => server.close())
    await once(server, 'listening')

    const pool = new Pool(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(() => pool.close())

    const first = await pool.request({ method: 'GET', path: '/' })
    strictEqual(await first.body.text(), 'response-body')
    strictEqual(requestsToOrigin, 1)

    const second = await pool.request({ method: 'GET', path: '/' })
    strictEqual(await second.body.text(), 'response-body')
    strictEqual(requestsToOrigin, 1, 'second request should be served from the cache')
  })

  test('cache() keeps distinct paths in distinct cache entries on a Client', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      requestsToOrigin++
      res.setHeader('cache-control', 'public, s-maxage=100')
      res.end(`body-for-${req.url}`)
    }).listen(0)

    after(() => server.close())
    await once(server, 'listening')

    const client = new Client(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(() => client.close())

    const first = await client.request({ method: 'GET', path: '/one' })
    strictEqual(await first.body.text(), 'body-for-/one')

    const second = await client.request({ method: 'GET', path: '/two' })
    strictEqual(await second.body.text(), 'body-for-/two')
