      requestsToOrigin++
      res.setHeader('cache-control', 'public, s-maxage=100')
      res.end('response-body')
    }).listen(0)

    after(() => server.close())
    await once(server, 'listening')

    const client = new Client(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(() => client.close())

    const first = await client.request({ method: 'GET', path: '/' })
    strictEqual(await first.body.text(), 'response-body')
    strictEqual(requestsToOrigin, 1)

    const second = await client.request({ method: 'GET', path: '/' })
    strictEqual(await second.body.text(), 'response-body')
    strictEqual(requestsToOrigin, 1, 'second request should be served from the cache')
  })

  test('cache() caches responses on a Pool', async () => {
    let requestsToOrigin = 0
    const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
      requestsToOrigin++
      res.setHeader('cache-control', 'public, s-maxage=100')
      res.end('response-body')
    }).listen(0)

    after(() => server.close())
    await once(server, 'listening')

    const pool = new Pool(`http://localhost:${server.address().port}`)
      .compose(interceptors.cache())

    after(() => pool.close())

